content = open(GEN, encoding='utf-8').read()

def dec(x):
    x = re.sub(r'\\u\{([0-9A-Fa-f]+)\}', lambda m: chr(int(m.group(1), 16)), x)
    x = re.sub(r'\\u([0-9A-Fa-f]{4})', lambda m: chr(int(m.group(1), 16)), x)
    return x

def block(src, name):
    a = src.index(name + '=') + len(name + '=')
    d = 0; k = a; ins = None; esc = False
    while k < len(src):
        c = src[k]
        if ins:
            if esc: esc = False
            elif c == '\\': esc = True
            elif c == ins: ins = None
        else:
            if c in '"\'`': ins = c
            elif c == '{': d += 1
            elif c == '}':
                d -= 1
                if d == 0: k += 1; break
        k += 1
    return src[a:k]

hlb = [dec(v) for v in re.findall(r':"([^"]*)"', block(content, 'const HL_BETA_PROMPTS'))]
beta = block(content, 'const BETA_GAMEDATA')
prompts = sorted(set(dec(m) for m in re.findall(r'\bprompt:"([^"]*)"', beta)))
mcq = sorted(set(dec(m) for m in re.findall(r'\bq:"([^"]*)"', beta)))
